"""Static reference data generated by scripts/build_reference_data.py."""

from __future__ import annotations

import base64
import json
import zlib
from dataclasses import dataclass
from pathlib import Path
from typing import Any

from .const import (
    CATALOG_MATCH_RADIUS_M,
    CATALOG_ZONES,
    DISTRICT_MATCH_RADIUS_M,
    MountZone,
)
from .geo import distance_m

DATA_DIR = Path(__file__).parent / "data"


@dataclass(frozen=True, slots=True)
class CatalogEntry:
    """Siting metadata of one catalogued sensor module."""

    code: str
    hardware: str | None
    latitude: float
    longitude: float
    height_above_ground: int | None
    temperature_height: int | None
    zone: MountZone | None
    lcz: int | None


@dataclass(frozen=True, slots=True)
class LczGrid:
    """Local Climate Zone raster, row-major from north-west."""

    north: float
    west: float
    step_lat: float
    step_lon: float
    rows: int
    cols: int
    cells: bytes

    def lookup(self, latitude: float, longitude: float) -> int | None:
        """Return the LCZ class at a coordinate, None outside the grid or no data."""
        row = int((self.north - latitude) / self.step_lat)
        col = int((longitude - self.west) / self.step_lon)
        if not (0 <= row < self.rows and 0 <= col < self.cols):
            return None
        return self.cells[row * self.cols + col] or None


@dataclass(frozen=True, slots=True)
class District:
    """Name of the district around a station location."""

    latitude: float
    longitude: float
    name: str


class ReferenceData:
    """Lookups into the bundled catalogue, LCZ grid and district names."""

    def __init__(
        self,
        catalog: list[CatalogEntry],
        lcz_grid: LczGrid,
        districts: list[District],
    ) -> None:
        """Index the data for name lookups."""
        self._catalog = catalog
        self._by_name: dict[str, CatalogEntry] = {}
        for entry in catalog:
            self._by_name.setdefault(entry.code, entry)
            if entry.hardware:
                self._by_name.setdefault(entry.hardware, entry)
        self._lcz_grid = lcz_grid
        self._districts = districts

    def catalog_entry(
        self, names: list[str], latitude: float, longitude: float
    ) -> CatalogEntry | None:
        """Find a station's catalogue entry by sensor name, else by position."""
        for name in names:
            if entry := self._by_name.get(name):
                return entry
        nearby = [
            (distance, entry)
            for entry in self._catalog
            if (
                distance := distance_m(
                    latitude, longitude, entry.latitude, entry.longitude
                )
            )
            <= CATALOG_MATCH_RADIUS_M
        ]
        # Prefer the temperature module over a co-located wind module.
        nearby.sort(key=lambda item: (item[1].temperature_height is None, item[0]))
        return nearby[0][1] if nearby else None

    def lcz(self, latitude: float, longitude: float) -> int | None:
        """Return the mapped LCZ class at a coordinate."""
        return self._lcz_grid.lookup(latitude, longitude)

    def district(self, latitude: float, longitude: float) -> str | None:
        """Return the district name of the nearest known station location."""
        nearest = min(
            self._districts,
            key=lambda district: distance_m(
                latitude, longitude, district.latitude, district.longitude
            ),
            default=None,
        )
        if nearest and (
            distance_m(latitude, longitude, nearest.latitude, nearest.longitude)
            <= DISTRICT_MATCH_RADIUS_M
        ):
            return nearest.name
        return None


def _read(name: str) -> dict[str, Any]:
    return json.loads((DATA_DIR / name).read_text(encoding="utf-8"))


def load_reference_data() -> ReferenceData:
    """Load all bundled files (blocking, run in the executor)."""
    catalog = [
        CatalogEntry(
            code=raw["code"],
            hardware=raw.get("hardware"),
            latitude=raw["lat"],
            longitude=raw["lon"],
            height_above_ground=raw.get("height_above_ground"),
            temperature_height=raw.get("temperature_height"),
            zone=CATALOG_ZONES.get(raw.get("zone")),
            lcz=raw.get("lcz"),
        )
        for raw in _read("catalog.json")["stations"]
    ]
    grid = _read("lcz_grid.json")
    lcz_grid = LczGrid(
        north=grid["north"],
        west=grid["west"],
        step_lat=grid["step_lat"],
        step_lon=grid["step_lon"],
        rows=grid["rows"],
        cols=grid["cols"],
        cells=zlib.decompress(base64.b64decode(grid["data"])),
    )
    districts = [
        District(latitude=raw["lat"], longitude=raw["lon"], name=raw["name"])
        for raw in _read("districts.json")["districts"]
    ]
    return ReferenceData(catalog, lcz_grid, districts)
